<div class="custom-faq-accordion" aria-label="Frequently Asked Questions"><h2 id="frequently-asked-questions">Frequently Asked Questions</h2><div class="faq-item"><button class="faq-question open" type="button" aria-expanded="true" aria-controls="faq-answer-0"><span class="faq-title"><h3 id="can-i-send-gst-or-tax-compliant-invoices-through-whatsapp">Can I send GST- or tax-compliant invoices through WhatsApp?</h3></span><span class="faq-arrow" aria-hidden="true"></span></button><div id="faq-answer-0" class="faq-answer open" role="region" aria-hidden="false" style="max-height:none;">Yes. Businesses can send GST- and tax-compliant invoices on WhatsApp as PDF documents, provided the document itself contains all mandatory fields.</div></div><div class="faq-item"><button class="faq-question" type="button" aria-expanded="false" aria-controls="faq-answer-1"><span class="faq-title"><h3 id="do-i-need-coding-skills-to-automate-invoice-sending-via-whatsapp">Do I need coding skills to automate invoice sending via WhatsApp?</h3></span><span class="faq-arrow" aria-hidden="true"></span></button><div id="faq-answer-1" class="faq-answer" role="region" aria-hidden="true">No. WhatsApp automation platforms like HelloBotz let you automate invoice delivery, payment reminders, and receipts without writing a single line of code.</div></div><div class="faq-item"><button class="faq-question" type="button" aria-expanded="false" aria-controls="faq-answer-2"><span class="faq-title"><h3 id="is-it-possible-to-schedule-payment-reminders-on-the-whatsapp-api">Is it possible to schedule payment reminders on the WhatsApp API?</h3></span><span class="faq-arrow" aria-hidden="true"></span></button><div id="faq-answer-2" class="faq-answer" role="region" aria-hidden="true">Yes. The WhatsApp Business API lets brands schedule their payment reminders to deliver automatically before or after invoice due dates. It reduces overdue payments and manual follow-ups.</div></div><div class="faq-item"><button class="faq-question" type="button" aria-expanded="false" aria-controls="faq-answer-3"><span class="faq-title"><h3 id="what-happens-if-my-whatsapp-invoice-template-gets-rejected">What happens if my WhatsApp invoice template gets rejected?</h3></span><span class="faq-arrow" aria-hidden="true"></span></button><div id="faq-answer-3" class="faq-answer" role="region" aria-hidden="true">If your template gets rejected, Meta generally gives you a reason behind it. You just need to fix the issue and submit it for review.</div></div><div class="faq-item"><button class="faq-question" type="button" aria-expanded="false" aria-controls="faq-answer-4"><span class="faq-title"><h3 id="can-customers-pay-their-invoice-directly-inside-whatsapp">Can customers pay their invoice directly inside WhatsApp?</h3></span><span class="faq-arrow" aria-hidden="true"></span></button><div id="faq-answer-4" class="faq-answer" role="region" aria-hidden="true">Yes. You can add UPI, card, or payment links in your invoice messages on WhatsApp to let customers pay within the chat with just a few clicks.</div></div></div><script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Can I send GST- or tax-compliant invoices through WhatsApp?","acceptedAnswer":{"@type":"Answer","text":"Yes. Businesses can send GST- and tax-compliant invoices on WhatsApp as PDF documents, provided the document itself contains all mandatory fields."}},{"@type":"Question","name":"Do I need coding skills to automate invoice sending via WhatsApp?","acceptedAnswer":{"@type":"Answer","text":"No. WhatsApp automation platforms like HelloBotz let you automate invoice delivery, payment reminders, and receipts without writing a single line of code."}},{"@type":"Question","name":"Is it possible to schedule payment reminders on the WhatsApp API?","acceptedAnswer":{"@type":"Answer","text":"Yes. The WhatsApp Business API lets brands schedule their payment reminders to deliver automatically before or after invoice due dates. It reduces overdue payments and manual follow-ups."}},{"@type":"Question","name":"What happens if my WhatsApp invoice template gets rejected?","acceptedAnswer":{"@type":"Answer","text":"If your template gets rejected, Meta generally gives you a reason behind it. You just need to fix the issue and submit it for review."}},{"@type":"Question","name":"Can customers pay their invoice directly inside WhatsApp?","acceptedAnswer":{"@type":"Answer","text":"Yes. You can add UPI, card, or payment links in your invoice messages on WhatsApp to let customers pay within the chat with just a few clicks."}}]}</script>
    <script>
    (function(){
        if (window.__customFaqAccordionInit) return;
        window.__customFaqAccordionInit = true;

        function closeAnswer(answer, btn) {
            if (!answer) return;
            // if maxHeight is "none", set to current px value to animate to 0
            if (answer.style.maxHeight === "none" || answer.style.maxHeight === "") {
                answer.style.maxHeight = answer.scrollHeight + "px";
            }
            // force reflow
            void answer.offsetHeight;
            answer.style.maxHeight = "0px";
            answer.classList.remove("open");
            if (btn) {
                btn.classList.remove("open");
                btn.setAttribute("aria-expanded", "false");
            }
            answer.setAttribute("aria-hidden", "true");
        }

        function openAnswer(answer, btn) {
            if (!answer) return;
            // set to exact height so transition works
            answer.style.maxHeight = answer.scrollHeight + "px";
            answer.classList.add("open");
            if (btn) {
                btn.classList.add("open");
                btn.setAttribute("aria-expanded", "true");
            }
            answer.setAttribute("aria-hidden", "false");

            // once transition finishes, set to none to allow internal content changes (images) without clipping
            var onTransEnd = function(e){
                if (answer.classList.contains("open")) {
                    answer.style.maxHeight = "none";
                }
                answer.removeEventListener("transitionend", onTransEnd);
            };
            answer.addEventListener("transitionend", onTransEnd);
        }

        document.addEventListener("click", function(e){
            var btn = e.target.closest ? e.target.closest(".custom-faq-accordion .faq-question") : null;
            if (!btn) return;

            var item = btn.closest(".faq-item");
            if (!item) return;
            var answer = item.querySelector(".faq-answer");
            if (!answer) return;

            // if already open, close it
            if (answer.classList.contains("open")) {
                closeAnswer(answer, btn);
            } else {
                // optionally close other open items (uncomment to allow only-one-open)
                var openItems = document.querySelectorAll(".custom-faq-accordion .faq-answer.open");
                openItems.forEach(function(o){
                    var parentBtn = o.closest(".faq-item") ? o.closest(".faq-item").querySelector(".faq-question") : null;
                    if (o !== answer) closeAnswer(o, parentBtn);
                });

                openAnswer(answer, btn);
            }
        });

        // Make sure open answers recalc height on window resize (useful if images load or layout changes)
        window.addEventListener("resize", function(){
            var openAnswers = document.querySelectorAll(".custom-faq-accordion .faq-answer.open");
            openAnswers.forEach(function(a){
                // if maxHeight is "none", set it to scrollHeight to keep it visible after resize
                if (a.style.maxHeight === "none") {
                    a.style.maxHeight = a.scrollHeight + "px";
                    // then release to none after a tick
                    setTimeout(function(){ a.style.maxHeight = "none"; }, 350);
                }
            });
        });
    })();
    </script>
    
